  9→  onSubagentText?: (data: { id: string; name: string; text: string }) => void;
 10→  onSubagentEnd?: (data: { id: string; name: string; result?: string; chart_spec?: { data: unknown[]; layout?: Record<string, unknown> } }) => void;
