100→export async function runAgentLoop(
101→  message: string,
102→  agentSessionId: string | null,
103→  langfuseSessionId: string | null,
104→  conversationHistory: { role: string; content: string }[] | null,
105→  callbacks: AgentCallbacks,
106→  signal?: AbortSignal,
107→  userSessionId?: string,
108→): Promise<void> {
109→  try {
110→    const response = await fetch('/api/chat', {
111→      method: 'POST',
112→      headers: {
113→        'Content-Type': 'application/json',
114→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
115→      },
116→      body: JSON.stringify({
117→        message,
118→        session_id: agentSessionId,
119→        langfuse_session_id: langfuseSessionId,
120→        conversation_history: conversationHistory ?? [],
121→      }),
122→      signal,
123→    });
124→
125→    if (!response.ok) {
126→      const errorText = await response.text();
127→      callbacks.onError(`Server error: ${errorText}`);
128→      return;
129→    }
130→
131→    await streamSSE(response, callbacks, signal);
132→  } catch (e: unknown) {
133→    if (signal?.aborted) return;
134→    const msg = e instanceof Error ? e.message : 'Connection failed';
135→    callbacks.onError(msg);
136→  }
