176→function handleSSEEvent(
177→  eventType: string,
178→  data: Record<string, unknown>,
179→  callbacks: AgentCallbacks,
180→) {
181→  switch (eventType) {
182→    case 'thinking':
183→    case 'answer':
184→      callbacks.onTextChunk(data.text as string);
185→      break;
186→    case 'thinking_done':
187→      callbacks.onThinkingDone();
188→      break;
189→    case 'tool_call':
190→      callbacks.onToolCall({
191→        toolCallId: (data.id as string) ?? '',
192→        toolName: (data.name as string) ?? undefined,
193→        sql: (data.sql as string) ?? '',
194→        command: (data.command as string) ?? undefined,
195→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
196→        columns: [],
197→        rows: [],
198→        rowCount: 0,
199→      });
200→      break;

200→      break;
201→    case 'tool_result': {
202→      const result: ToolCallResult = {
203→        toolCallId: (data.id as string) ?? '',
204→        toolName: (data.name as string) ?? undefined,
205→        sql: (data.sql as string) ?? '',
206→        columns: (data.columns as string[]) ?? [],
207→        rows: (data.rows as Record<string, unknown>[]) ?? [],
208→        rowCount: (data.rowCount as number) ?? 0,
209→        error: (data.error as string) ?? undefined,
210→        output: (data.output as string) ?? undefined,
211→        rawContent: (data.content as string) ?? undefined,
212→        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
213→      };
214→      callbacks.onToolResult(result);
215→      break;
216→    }
217→    case 'subagent_start':
218→      callbacks.onSubagentStart?.({
219→        id: data.id as string,
220→        name: data.name as string,
221→        prompt: (data.prompt as string) ?? '',
222→      });
223→      break;
224→    case 'subagent_text':
225→      callbacks.onSubagentText?.({
226→        id: data.id as string,
227→        name: data.name as string,
228→        text: data.text as string,
229→      });
230→      break;
231→    case 'subagent_end':
